INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-nugget-casino-urising-sun', 'GAMEBOYADVANCE', 'Golden Nugget Casino (U)(Rising Sun)', '2003', 'Casino', 'Majesco', '1', 'Gambling Simulation', 'Casino Simulation.', 'Win big in various classic casino games.', 'A comprehensive collection of Las Vegas-style gambling.', 'Golden Nugget Casino (US) features Blackjack, Roulette, Craps, and Slots. Manage your bankroll and try your luck in this realistic and portable casino experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-sun-fmoleia', 'GAMEBOYADVANCE', 'Golden Sun (F)(Moleia)', '2001', 'RPG', 'Camelot', '1', 'Turn-Based RPG', 'Turn-based RPG.', 'Prevent the release of Alchemy and save Weyard.', 'A French-localized masterpiece of the GBA RPG library.', 'Golden Sun (France) is a technical marvel featuring "Psynergy" puzzles and "Djinn" collection. Experience the epic journey of Isaac and his friends with a beautiful French translation.');
