INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('golden-sun-sindependent', 'GAMEBOYADVANCE', 'Golden Sun (S)(Independent)', '2001', 'RPG', 'Camelot', '1', 'Turn-Based RPG', 'Turn-based RPG.', 'Prevent the release of Alchemy and save Weyard.', 'A Spanish-localized masterpiece of the GBA RPG library.', 'Golden Sun (Spain) offers a flawless translation of Camelot''s classic RPG. Solve environmental puzzles using magic and build a powerful party to save the world of Weyard.');
