INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('granbo-jlord-moyne', 'GAMEBOYADVANCE', 'Granbo (J)(Lord Moyne)', '2001', 'Action', 'Hudson Soft', '1', 'Action Platformer', 'Monster-battling RPG.', 'Collect and upgrade robotic creatures called Granbo.', 'A charming robot-collecting RPG by Capcom.', 'Granbo (Japan) features strategic turn-based combat. Swap parts and upgrade your robots to save the world from a digital virus in this colorful and creative Japanese exclusive.');
