INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunstar-future-heroes-erising-sun', 'GAMEBOYADVANCE', 'Gunstar Future Heroes (E)(Rising Sun)', '2001', 'Action', 'Treasure', '1', 'Run and Gun', 'Side-scrolling run-and-gun.', 'Save the Seven Moons from the Empire.', 'A breathtaking sequel to the Genesis classic.', 'Gunstar Future Heroes (Europe) is a technical marvel. Featuring massive bosses, Mode-7 effects, and non-stop action, it is widely considered one of the best games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunstar-super-heroes-jwrg', 'GAMEBOYADVANCE', 'Gunstar Super Heroes (J)(WRG)', '2001', 'Action', 'Treasure', '1', 'Run and Gun', 'Side-scrolling run-and-gun.', 'Save the Seven Moons from the Empire.', 'The original Japanese release of the Gunstar sequel.', 'Gunstar Super Heroes (Japan) delivers frantic shooting action. Switch between various weapon types and master the melee combat in this high-energy Treasure-developed masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunstar-super-heroes-utrashman', 'GAMEBOYADVANCE', 'Gunstar Super Heroes (U)(Trashman)', '2001', 'Action', 'Treasure', '1', 'Run and Gun', 'Side-scrolling run-and-gun.', 'Save the Seven Moons from the Empire.', 'The US version of the legendary action game.', 'Gunstar Super Heroes (US) features incredible production values. Experience the "Seven Force" boss fight and high-speed chase sequences in this definitive handheld action experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guru-logic-champ-jnobody', 'GAMEBOYADVANCE', 'Guru Logic Champ (J)(Nobody)', '2001', 'Puzzle', 'Compile', '1', 'Logic Puzzle', 'Logic puzzle / Strategy.', 'Solve grid-based puzzles by manipulating blocks.', 'A quirky and addictive Japanese puzzle game.', 'Guru Logic Champ (Japan) requires spatial reasoning and strategy. Use the unique block-throwing mechanics to fill patterns and clear levels in this charming and brain-teasing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-jlightforce', 'GAMEBOYADVANCE', 'Gyakuten Saiban (J)(Lightforce)', '2001', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Courtroom drama / Visual Novel.', 'Defend your clients and find the truth in court.', 'The legendary debut of Phoenix Wright (Ryūichi Naruhodō).', 'Gyakuten Saiban (Japan) is a brilliant courtroom adventure. Investigate crime scenes, cross-examine witnesses, and shout "Igiari!" (Objection!) to uncover contradictions in this gripping legal thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-2-jhp', 'GAMEBOYADVANCE', 'Gyakuten Saiban 2 (J)(HP)', '2002', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Courtroom drama / Visual Novel.', 'Win complex legal battles and manage the "Psyche-Lock."', 'The high-stakes sequel to the hit legal drama.', 'Gyakuten Saiban 2 features deeper investigation mechanics. Help Phoenix Wright solve four intense cases while introducing the Psyche-Lock system to break through witness''s secrets on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-3-jsuxxors', 'GAMEBOYADVANCE', 'Gyakuten Saiban 3 (J)(Suxxors)', '2004', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Courtroom drama / Visual Novel.', 'Solve the mysteries of the past and present in court.', 'The epic conclusion to the original Ace Attorney trilogy.', 'Gyakuten Saiban 3 is widely considered the best in the series. Experience five emotional cases that bridge the gap between past and present, featuring both Phoenix and Mia Fey in their legal prime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gyakuten-saiban-best-price-jindependent', 'GAMEBOYADVANCE', 'Gyakuten Saiban Best Price (J)(Independent)', '2001', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Courtroom drama / Visual Novel.', 'Defend your clients and find the truth in court.', 'A budget re-release of the first Gyakuten Saiban.', 'The "Best Price" edition offers the full original experience of the first Ace Attorney game. Perfect for collectors, it contains all the original investigation and courtroom drama that defined the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hachiemon-jrising-sun', 'GAMEBOYADVANCE', 'Hachiemon (J)(Rising Sun)', '2002', 'Puzzle', 'Nintendo', '1', 'Arcade Puzzle', '2D Side-scrolling platformer.', 'Use your giant lips to swing and defeat enemies.', 'A quirky and colorful platformer starring a lip-focused hero.', 'Hachiemon (Japan) is a unique action game where your primary tool is a pair of giant lips. Use them to grab enemies, swing from platforms, and solve puzzles in this vibrant and humorous Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hagane-no-renkinjutsushi---omoide-no-soumeikyoku-jcaravan', 'GAMEBOYADVANCE', 'Hagane no Renkinjutsushi - Omoide no Soumeikyoku (J)(Caravan)', '2003', 'RPG', 'Banpresto', '1', 'Turn-Based RPG', 'Turn-based RPG.', 'Solve the mystery of the "Sonata of Memories."', 'A deep RPG based on the Fullmetal Alchemist anime.', 'Hagane no Renkinjutsushi features the Elric brothers in an original story. Utilize alchemy-based combat and exploration to uncover secrets while meeting the full cast of the series in this polished RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hajime-no-ippo---the-fighting-jeurasia', 'GAMEBOYADVANCE', 'Hajime no Ippo - The Fighting (J)(Eurasia)', '2002', 'Sports', 'Grand Prix', '2', 'Boxing', 'Sports / Boxing simulation.', 'Rise through the ranks to become the world champion.', 'A technical and hard-hitting boxing game based on the anime.', 'Hajime no Ippo - The Fighting features incredible sprite work and deep mechanics. Master Ippo''s "Dempsey Roll" and other iconic moves in one of the most respected sports games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamepane-tokyo-myumyu-jindependent', 'GAMEBOYADVANCE', 'Hamepane Tokyo Myumyu (J)(Independent)', '2001', 'Puzzle', 'Jaleco', '1', 'Action Puzzle', 'Puzzle / Matching.', 'Clear the board with the Tokyo Mew Mew team.', 'A magical girl-themed puzzle game.', 'Hamepane Tokyo Myumyu combines fast-paced block matching with the charm of the anime. Help the Mew Mews defeat aliens through strategic puzzle-solving and special power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-club-4-jrising-sun', 'GAMEBOYADVANCE', 'Hamster Club 4 (J)(Rising Sun)', '2002', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation.', 'Raise and train the ultimate champion hamster.', 'A detailed life simulator for hamster lovers.', 'Hamster Club 4 (Japan) focuses on the daily care and training of your pet. Enter competitions and customize your hamster''s environment in this adorable and deep simulation title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-gurakubu-3-jpolla', 'GAMEBOYADVANCE', 'Hamster Gurakubu 3 (J)(Polla)', '2001', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation.', 'Raise and train the ultimate champion hamster.', 'The third entry in the popular Japanese hamster series.', 'Hamster Gurakubu 3 features mini-games and breeding mechanics. Manage your hamster''s diet and happiness to ensure they are ready for the grand hamster tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-monogatari-2-jnil', 'GAMEBOYADVANCE', 'Hamster Monogatari 2 (J)(Nil)', '2002', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation / RPG.', 'Journey through a miniature world with your hamster.', 'An adventure-focused hamster life simulator.', 'Hamster Monogatari 2 features exploration elements alongside traditional pet care. Help your hamster interact with the world and other pets in this charming Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-monogatari-3-jpatience', 'GAMEBOYADVANCE', 'Hamster Monogatari 3 (J)(Patience)', '2003', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation / RPG.', 'Journey through a miniature world with your hamster.', 'The expanded third installment of the Hamster Story.', 'Hamster Monogatari 3 offers more locations and refined pet interactions. Breed unique hamster varieties and participate in various community events in this cozy handheld sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-monogatari-3ex-4-special-jwrg', 'GAMEBOYADVANCE', 'Hamster Monogatari 3EX 4 Special (J)(WRG)', '2004', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation / RPG.', 'Journey through a miniature world with your hamster.', 'A special "EX" edition with bonus content.', 'This 3EX 4 Special edition includes extra mini-games and rare hamster breeds. Experience the ultimate version of the Hamster Monogatari series with enhanced features for fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-monogatari-collection-jrising-sun', 'GAMEBOYADVANCE', 'Hamster Monogatari Collection (J)(Rising Sun)', '2004', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation Collection.', 'Enjoy a variety of hamster-themed games and tools.', 'A compilation of the best Hamster Monogatari moments.', 'Hamster Monogatari Collection bundles several mini-games and care simulators into one package. It''s the perfect entry point for those looking for the ultimate GBA hamster experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-paradise---pure-heart-jevasion', 'GAMEBOYADVANCE', 'Hamster Paradise - Pure Heart (J)(Evasion)', '2003', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation.', 'Build a strong bond with your pet hamster.', 'A "Pure Heart" themed life simulator.', 'Hamster Paradise features social interactions and emotional bonding. Use the GBA''s internal clock to manage your pet''s life and discover heart-themed secrets and mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamster-paradise-advance-jchakky', 'GAMEBOYADVANCE', 'Hamster Paradise Advance (J)(Chakky)', '2001', 'Simulation', 'Nintendo', '1', 'Pet Simulation', 'Pet Simulation.', 'Build a strong bond with your pet hamster.', 'The foundational GBA entry in the Hamster Paradise series.', 'Hamster Paradise Advance focuses on high-quality animations and diverse mini-games. Care for your hamster''s every need and watch them grow in this polished Japanese pet sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamtaro---ham-ham-games-erising-sun', 'GAMEBOYADVANCE', 'Hamtaro - Ham-Ham Games (E)(Rising Sun)', '2002', 'Sports', 'AlphaDream', '4', 'Party Sports', 'Sports / Mini-game collection.', 'Win the gold medal in the Ham-Ham Games.', 'An Olympic-style sports game starring Hamtaro.', 'Hamtaro - Ham-Ham Games (Europe) features events like sprinting, swimming, and archery. Help Hamtaro and his friends compete in a variety of cute and challenging athletic competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamtaro---ham-ham-heartbreak-esurplus', 'GAMEBOYADVANCE', 'Hamtaro - Ham-Ham Heartbreak (E)(Surplus)', '2002', 'Adventure', 'AlphaDream', '1', 'Story Adventure', 'Adventure / RPG.', 'Restore love and friendship to the Ham-Ham world.', 'A heartwarming adventure to stop the evil Spat.', 'Ham-Ham Heartbreak (Europe) is a fan-favorite RPG. Learn new "Ham-Chat" words to interact with the environment and solve puzzles to fix the broken relationships in the neighborhood.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamtaro---ham-ham-heartbreak-uvenom', 'GAMEBOYADVANCE', 'Hamtaro - Ham-Ham Heartbreak (U)(Venom)', '2003', 'Adventure', 'AlphaDream', '1', 'Story Adventure', 'Adventure / RPG.', 'Restore love and friendship to the Ham-Ham world.', 'The US version of the beloved Hamtaro adventure.', 'The US release of Ham-Ham Heartbreak features a charming story and addictive collection mechanics. Explore diverse locations like Sunny Peak and Sandy Bay to stop Spat''s mischievous plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hamtaro---rainbow-rescue-erising-sun', 'GAMEBOYADVANCE', 'Hamtaro - Rainbow Rescue (E)(Rising Sun)', '2004', 'Adventure', 'AlphaDream', '1', 'Story Adventure', 'Adventure / Puzzle.', 'Save the Rainbow Prince and restore the colors.', 'A colorful adventure featuring the full Ham-Ham gang.', 'Hamtaro - Rainbow Rescue (Europe) requires you to use the unique skills of different hamsters. Switch between characters to solve environmental puzzles and bring color back to the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanabi-hyakkei-advance-jcaravan', 'GAMEBOYADVANCE', 'Hanabi Hyakkei Advance (J)(Caravan)', '2003', 'Action', 'Nintendo', '1', 'Fireworks Action', 'Simulation / Pachislot.', 'Master the Hanabi Hyakkei slot machine.', 'A realistic gambling simulator for Japanese fans.', 'Hanabi Hyakkei Advance brings the popular Japanese "pachi-slot" experience to GBA. Practice your timing and manage your virtual coins in this faithful recreation of the arcade original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hanafuda-trump-mahjong-depachika-wayouchuu-jkamx', 'GAMEBOYADVANCE', 'Hanafuda Trump Mahjong Depachika Wayouchuu (J)(kaMX)', '2002', 'Card', 'Gamebridge', '4', 'Traditional Card Game', 'Card / Board Game Collection.', 'Win at traditional Japanese card and tile games.', 'A 3-in-1 pack featuring Hanafuda and Mahjong.', 'This collection offers Hanafuda, Trump (Western cards), and Mahjong. Perfect for fans of traditional games, it features smart AI and a variety of rule sets to master on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-feet-erising-sun', 'GAMEBOYADVANCE', 'Happy Feet (E)(Rising Sun)', '2006', 'Platformer', 'Krome Studios', '1', 'Action Platformer', 'Rhythm / Music Adventure.', 'Dance your way to the heart of the penguin colony.', 'A rhythm-based adventure based on the Pixar film.', 'Happy Feet (Europe) features Mumble in a quest to save his people. Use rhythmic button presses to "tap dance" through various levels and overcome predators in the icy Antarctic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('happy-feet-urising-sun', 'GAMEBOYADVANCE', 'Happy Feet (U)(Rising Sun)', '2006', 'Platformer', 'Krome Studios', '1', 'Action Platformer', 'Rhythm / Music Adventure.', 'Dance your way to the heart of the penguin colony.', 'The US version of the musical penguin quest.', 'Happy Feet (US) captures the energy of the movie. Master the rhythm-action sequences and explore the frozen wilderness in this family-friendly handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardcore-pinball-uquartex', 'GAMEBOYADVANCE', 'Hardcore Pinball (U)(Quartex)', '2002', 'Arcade', 'Teque London', '4', 'Pinball', 'Pinball Simulation.', 'Earn high scores across multiple themed tables.', 'A fast-paced and realistic pinball simulator.', 'Hardcore Pinball features tables based on different themes like sci-fi and horror. Experience realistic ball physics and challenging multiball modes in this arcade-style GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardcore-pool-esupplex', 'GAMEBOYADVANCE', 'Hardcore Pool (E)(sUppLeX)', '2004', 'Sports', 'Easy Interactive', '2', 'Pool Simulation', 'Sports / Billiards simulation.', 'Clear the table and win the professional pool tour.', 'A precise and technical pool game for the GBA.', 'Hardcore Pool (Europe) offers various game modes including 8-ball and 9-ball. Master the physics-based aiming system to sink shots and defeat the toughest AI opponents in the circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harlem-globetrotters---world-tour-usir-vg', 'GAMEBOYADVANCE', 'Harlem Globetrotters - World Tour (U)(Sir VG)', '2006', 'Sports', 'Full Fat', '2', 'Basketball Arcade', 'Sports / Basketball.', 'Perform amazing tricks and win exhibition games.', 'A fun and flashy basketball game featuring the Globetrotters.', 'Harlem Globetrotters - World Tour features the team''s signature comedy and trick shots. Play through a global tour, performing "showman" moves and alley-oops in this accessible sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haro-no-puyo-puyo-jcaravan', 'GAMEBOYADVANCE', 'Haro no Puyo Puyo (J)(Caravan)', '2001', 'Puzzle', 'Compile', '2', 'Falling Block Puzzle', 'Puzzle / Matching.', 'Defeat rivals in a classic Puyo Puyo battle.', 'A special "Gundam Haro" version of the puzzle hit.', 'Haro no Puyo Puyo (Japan) replaces the classic slimes with the iconic Haro robots from Gundam. Experience the same addictive chain-reaction puzzle gameplay with a fun sci-fi twist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harobots---robo-hero-battling-jchakky', 'GAMEBOYADVANCE', 'Harobots - Robo Hero Battling (J)(Chakky)', '2002', 'Action', 'MTO', '2', 'Arena Combat', 'Tactical RPG / Battler.', 'Build and battle your own team of Harobots.', 'A robot-collecting strategy game featuring Gundam mechs.', 'Harobots: Robo Hero Battling features iconic mechs from various Gundam series in SD (Super Deformed) style. Collect parts, customize your robots, and engage in tactical grid-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter---quidditch-world-cup-jrising-sun', 'GAMEBOYADVANCE', 'Harry Potter - Quidditch World Cup (J)(Rising Sun)', '2003', 'Sports', 'Electronic Arts', '4', 'Arcade Sports', 'Sports / Action.', 'Win the Quidditch World Cup for your school or nation.', 'Fly and score in the magical sport of the wizarding world.', 'Harry Potter - Quidditch World Cup (Japan) brings the excitement of broomstick racing and scoring to GBA. Master the Chaser and Seeker roles to lead your team to international glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter---quidditch-world-cup-urising-sun', 'GAMEBOYADVANCE', 'Harry Potter - Quidditch World Cup (U)(Rising Sun)', '2002', 'Action Adventure', 'EA UK', '1', 'Action Adventure', 'Sports / Action.', 'Win the Quidditch World Cup for your school or nation.', 'Fly and score in the magical sport of the wizarding world.', 'The US version of Quidditch World Cup features fast-paced aerial gameplay. Build your team, learn special moves, and execute the perfect Snitch catch in this unique magical sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-chamber-of-secrets-umode7', 'GAMEBOYADVANCE', 'Harry Potter and the Chamber of Secrets (U)(Mode7)', '2004', 'Action Adventure', 'Electronic Arts', '1', 'Action Adventure', 'Action-Adventure.', 'Navigate Hogwarts to uncover the Chamber of Secrets.', 'A 2D top-down adventure based on the second book.', 'Harry Potter and the Chamber of Secrets (US) features exploration, spell-casting, and stealth. Solve environmental puzzles and battle legendary creatures like the Basilisk on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-goblet-of-fire-urising-sun', 'GAMEBOYADVANCE', 'Harry Potter and the Goblet of Fire (U)(Rising Sun)', '2007', 'Action Adventure', 'Electronic Arts', '1', 'Action Adventure', 'Isometric Action.', 'Survive the Triwizard Tournament and defeat Voldemort.', 'A team-based action game featuring Harry, Ron, and Hermione.', 'The Goblet of Fire (US) focuses on cooperative-style gameplay. Combine spells with your friends to overcome the Triwizard tasks and the dark forces of the graveyard in this cinematic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-order-of-the-phoenix-usupplex', 'GAMEBOYADVANCE', 'Harry Potter And The Order Of The Phoenix (U)(sUppLeX)', '2004', 'Action Adventure', 'EA UK', '1', 'Action Adventure', 'Adventure / Mini-games.', 'Form Dumbledore''s Army and explore a 3D-style Hogwarts.', 'A late-release GBA title with impressive scale.', 'The Order of the Phoenix (US) lets you explore a highly detailed Hogwarts. Recruit students, complete missions, and master advanced magic in this ambitious handheld movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-prisoner-of-azkaban-uvenom', 'GAMEBOYADVANCE', 'Harry Potter and the Prisoner of Azkaban (U)(Venom)', '2001', 'Action Adventure', 'KnowWonder', '1', 'Action Adventure', 'Turn-based RPG.', 'Find Sirius Black and protect Hogwarts from Dementors.', 'A high-quality RPG that stays true to the novel''s plot.', 'Prisoner of Azkaban (US) is a standout GBA RPG. Manage a party of three, level up their magical stats, and use the unique "Expecto Patronum" spell in strategic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-sorcerers-stone-ulightforce', 'GAMEBOYADVANCE', 'Harry Potter and the Sorcerer''s Stone (U)(Lightforce)', '2003', 'Compilation', 'Electronic Arts', '1', 'Game Collection', 'Action-Adventure.', 'Find the Sorcerer''s Stone and stop Professor Quirrell.', 'The magical debut of Harry Potter on the GBA.', 'Harry Potter and the Sorcerer''s Stone (US) features classic top-down adventure gameplay. Attend classes, learn iconic spells like Wingardium Leviosa, and explore the mysteries of Hogwarts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-collection-epuppa', 'GAMEBOYADVANCE', 'Harry Potter Collection (E)(Puppa)', '2004', 'Action Adventure', 'EA UK', '1', 'Action Adventure', 'Adventure Collection.', 'Experience Harry''s early years in one package.', 'A 2-in-1 bundle of the first two Harry Potter GBA games.', 'The Harry Potter Collection (Europe) brings the Sorcerer''s Stone and Chamber of Secrets together. It''s the ultimate way for fans to relive the beginning of the saga on a single cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-to-azkaban-no-shuujin-jcaravan', 'GAMEBOYADVANCE', 'Harry Potter to Azkaban no Shuujin (J)(Caravan)', '2002', 'Action Adventure', 'Argonaut Games', '1', 'Action Adventure', 'Turn-based RPG.', 'Find Sirius Black and protect Hogwarts from Dementors.', 'The Japanese version of the Prisoner of Azkaban RPG.', 'Experience the best-rated Harry Potter game on GBA in Japanese. Follow the story of the third year with beautiful sprite work and deep role-playing mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-to-himitsu-no-heya-jevasion', 'GAMEBOYADVANCE', 'Harry Potter to Himitsu no Heya (J)(Evasion)', '2001', 'Action Adventure', 'KnowWonder', '1', 'Action Adventure', 'Action-Adventure.', 'Navigate Hogwarts to uncover the Chamber of Secrets.', 'The Japanese version of the Chamber of Secrets adventure.', 'Explore the secrets of Hogwarts with localized Japanese text. Use your wand to interact with the environment and solve the mystery of the heir of Slytherin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-to-kenja-no-ishi-jrapid-fire', 'GAMEBOYADVANCE', 'Harry Potter to Kenja no Ishi (J)(Rapid Fire)', '2002', 'Adventure', 'Koei', '1', 'Otome Visual Novel', 'Action-Adventure.', 'Find the Sorcerer''s Stone and stop Professor Quirrell.', 'The Japanese version of the first Harry Potter game.', 'Relive the magic of the first book in its Japanese GBA format. Master the art of dueling and potion-making in this faithful cinematic adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harukanaru-jikuu-no-naka-de-jchakky', 'GAMEBOYADVANCE', 'Harukanaru Jikuu no Naka de (J)(Chakky)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Visual Novel / Otome.', 'Travel back to the Heian period and protect the capital.', 'A romantic adventure with a deep historical story.', 'Harukanaru Jikuu no Naka de (Japan) features beautiful art and a branching narrative. Interact with the Eight Guardians to save the city and find love in this classic Otome title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---friends-of-mineral-town-egba', 'GAMEBOYADVANCE', 'Harvest Moon - Friends of Mineral Town (E)(GBA)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Life / Farming Simulation.', 'Restore your grandfather''s farm and start a family.', 'One of the most beloved farming simulators of all time.', 'Harvest Moon - Friends of Mineral Town (Europe) is a masterpiece of GBA simulation. Manage your crops, raise livestock, and build relationships in a town that changes with the seasons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---friends-of-mineral-town-grising-sun', 'GAMEBOYADVANCE', 'Harvest Moon - Friends of Mineral Town (G)(Rising Sun)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Life / Farming Simulation.', 'Restore your grandfather''s farm and start a family.', 'The German-localized version of the farming classic.', 'Friends of Mineral Town (Germany) offers the full, addictive experience of rural life. Experience the joy of the Harvest Festival and the daily rewards of hard work on the farm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---friends-of-mineral-town-umode7', 'GAMEBOYADVANCE', 'Harvest Moon - Friends of Mineral Town (U)(Mode7)', '2005', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Life / Farming Simulation.', 'Restore your grandfather''s farm and start a family.', 'The US version of the definitive farming RPG.', 'Harvest Moon - Friends of Mineral Town (US) set the bar for the genre. With hundreds of hours of gameplay, it’s a relaxing and rewarding journey into the heart of Mineral Town.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---more-friends-of-mineral-town-utrashman', 'GAMEBOYADVANCE', 'Harvest Moon - More Friends of Mineral Town (U)(Trashman)', '2001', 'Puzzle', 'Nintendo', '1', 'Logic Puzzle', 'Life / Farming Simulation.', 'Restore your grandfather''s farm and start a family.', 'The "girl version" of the classic Mineral Town game.', 'More Friends of Mineral Town (US) lets you play as a female protagonist. Featuring new marriage candidates and events, it adds a fresh perspective to the beloved farming formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hatena-satena-jeurasia', 'GAMEBOYADVANCE', 'Hatena Satena (J)(Eurasia)', '2003', 'Action Adventure', 'Griptonite Games', '1', 'Action Adventure', 'Puzzle / Strategy.', 'Paint the grid to reveal hidden pixel art.', 'A unique and colorful "Picross" style puzzle game.', 'Hatena Satena (Japan) features vibrant characters and addictive logic puzzles. Fill in the blocks correctly to clear stages in this visually striking Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haunted-mansion-the-usa-proto', 'GAMEBOYADVANCE', 'Haunted Mansion, The (USA) (Proto)', '2004', 'Adventure', 'Planet Interactive', '1', 'Story Adventure', 'Action-Adventure.', 'Explore the spooky mansion and solve the mystery.', 'A rare unreleased prototype of the Disney movie game.', 'The Haunted Mansion (USA Proto) offers a glimpse into a cancelled project. Explore eerie rooms and interact with spirits in this atmospheric adventure based on the classic ride.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heidi---the-game-erising-sun', 'GAMEBOYADVANCE', 'Heidi - The Game (E)(Rising Sun)', '2004', 'Simulation', 'Success', '1', 'Idol Simulation', 'Adventure / Mini-games.', 'Complete tasks in the Alps and help your friends.', 'A charming game based on the classic "Heidi" story.', 'Heidi - The Game (Europe) features the beloved orphan in a series of mountain-themed levels. Help Peter with the goats and explore the beautiful scenery in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-idol-debut-jcaravan', 'GAMEBOYADVANCE', 'Hello Idol Debut (J)(Caravan)', '2003', 'Party', 'Game Factory', '4', 'Party Mini-Games', 'Social Simulation / Music.', 'Train to become the top Japanese pop idol.', 'A colorful idol management and rhythm game.', 'Hello Idol Debut (Japan) lets you customize your character and practice dance routines. Manage your schedule and perform on stage to win the hearts of your fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---happy-party-pals-esir-vg', 'GAMEBOYADVANCE', 'Hello Kitty - Happy Party Pals (E)(Sir VG)', '2003', 'Party', 'Game Factory', '4', 'Party Mini-Games', 'Social Simulation / Mini-games.', 'Throw the perfect parties for Hello Kitty and friends.', 'A cute and festive social game starring Sanrio''s icon.', 'Hello Kitty - Happy Party Pals (Europe) is all about celebration. Plan themed parties, play mini-games, and collect decorations in this cheerful and accessible handheld game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---happy-party-pals-esupplex', 'GAMEBOYADVANCE', 'Hello Kitty - Happy Party Pals (E)(sUppLeX)', '2003', 'Party', 'Game Factory', '4', 'Party Mini-Games', 'Social Simulation / Mini-games.', 'Throw the perfect parties for Hello Kitty and friends.', 'An alternative European release of the party sim.', 'Help Hello Kitty organize events for all her Sanrio friends. Master various mini-games to earn points and unlock new outfits and accessories for your parties.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---happy-party-pals-utrashman', 'GAMEBOYADVANCE', 'Hello Kitty - Happy Party Pals (U)(Trashman)', '2001', 'Compilation', 'Sanrio', '1', 'Mini-Game Collection', 'Social Simulation / Mini-games.', 'Throw the perfect parties for Hello Kitty and friends.', 'The US version of the Hello Kitty party adventure.', 'Happy Party Pals (US) offers a safe and creative environment for younger players. Explore the town, talk to friends, and ensure every party is a smashing success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty-collection-miracle-jlightforce', 'GAMEBOYADVANCE', 'Hello Kitty Collection Miracle (J)(Lightforce)', '2002', 'Action Adventure', 'Altron', '1', 'Cartoon Adventure', 'Mini-game Collection.', 'Play through a series of "Miracle" themed challenges.', 'A diverse collection of Hello Kitty mini-games.', 'Hello Kitty Collection Miracle (Japan) features classic arcade-style gameplay with a Sanrio twist. From puzzles to action games, it’s a delightful variety pack for fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hey-arnold!-the-movie-easgard', 'GAMEBOYADVANCE', 'Hey Arnold! The Movie (E)(Asgard)', '2002', 'Action Adventure', 'Altron', '1', 'Cartoon Adventure', '2D Platformer / Stealth.', 'Save the neighborhood and stop the corporate developer.', 'A funny adventure based on the Hey Arnold! movie.', 'Hey Arnold! The Movie (Europe) features Arnold and Gerald in a quest to save their block. Use stealth and platforming to navigate the city and outsmart the Scheck corporation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hey-arnold!-the-movie-uvenom', 'GAMEBOYADVANCE', 'Hey Arnold! The Movie (U)(Venom)', '2006', 'Action Platformer', 'High Voltage Software', '1', 'Action Platformer', '2D Platformer / Stealth.', 'Save the neighborhood and stop the corporate developer.', 'The US version of the Nicktoon movie game.', 'Help Arnold and his friends protect their home on your GBA. This version captures the show''s urban atmosphere and features various gadgets to help you on your mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hi-hi-puffy-amiyumi---kaznapped-erising-sun', 'GAMEBOYADVANCE', 'Hi Hi Puffy AmiYumi - Kaznapped (E)(Rising Sun)', '2006', 'Action Platformer', 'High Voltage Software', '1', 'Action Platformer', '2D Side-scrolling Action.', 'Rescue the band''s manager and defeat Kaz.', 'A high-energy brawler based on the Hi Hi Puffy AmiYumi show.', 'Kaznapped (Europe) features the rock duo in a wacky adventure. Switch between Ami and Yumi to use their different abilities and instruments to defeat enemies and solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hi-hi-puffy-amiyumi---kaznapped-urising-sun', 'GAMEBOYADVANCE', 'Hi Hi Puffy AmiYumi - Kaznapped (U)(Rising Sun)', '2005', 'Action Platformer', 'Interchannel', '1', 'Action Platformer', '2D Side-scrolling Action.', 'Rescue the band''s manager and defeat Kaz.', 'The US version of the Puffy AmiYumi action hit.', 'Hi Hi Puffy AmiYumi - Kaznapped (US) delivers fast-paced platforming and rock-and-roll humor. Travel across the world to save your manager in this stylish and colorful GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hi-hi-puffy-amiyumi-jsupplex', 'GAMEBOYADVANCE', 'Hi Hi Puffy AmiYumi (J)(sUppLeX)', '2002', 'Adventure', 'Compile', '1', 'Dark Adventure', '2D Side-scrolling Action.', 'Rescue the band''s manager and defeat Kaz.', 'The Japanese release of the rock-themed adventure.', 'Experience the GBA debut of the J-Pop stars in their home market. Use the power of rock to blast through robotic enemies and rescue Kaz in this vibrant handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('higanbana-jpolla', 'GAMEBOYADVANCE', 'Higanbana (J)(Polla)', '2002', 'Action Adventure', 'Compile', '1', 'Dark Adventure', 'Horror / Visual Novel.', 'Uncover the terrifying truth behind the Higanbana legend.', 'A dark and atmospheric Japanese horror story.', 'Higanbana (Japan) is a psychological horror visual novel. Make choices that affect the outcome of the story as you investigate a series of mysterious and supernatural events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-heat---major-league-baseball-2002-umode7', 'GAMEBOYADVANCE', 'High Heat - Major League Baseball 2002 (U)(Mode7)', '2001', 'Sports', 'Baseball Sim', '2', 'Simulation', 'Realistic baseball simulation with manual pitching, batting, and fielding controls.', 'Win individual matches and lead your team to a World Series championship.', 'A comprehensive 2002 MLB simulation featuring official teams and players.', 'High Heat Major League Baseball 2002 offers authentic diamond action for GBA. Manage rosters and master the art of pitching in this classic handheld sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-heat---major-league-baseball-2003-umode7', 'GAMEBOYADVANCE', 'High Heat - Major League Baseball 2003 (U)(Mode7)', '2002', 'Sports', 'Baseball Sim', '2', 'Simulation', 'Arcade-style baseball mechanics with updated 2003 rosters and improved physics.', 'Dominate the league by winning games in Season or Exhibition modes.', 'The 2003 edition of the realistic MLB series with updated stats.', 'Experience the thrill of the big leagues in High Heat MLB 2003. Featuring precision batting and deep seasonal play, it’s a must-have for GBA sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-heat-major-league-baseball-2003-jchakky', 'GAMEBOYADVANCE', 'High Heat Major League Baseball 2003 (J)(Chakky)', '2002', 'Sports', 'Baseball Sim', '2', 'Simulation', 'Arcade-style baseball mechanics with updated 2003 rosters and improved physics.', 'Dominate the league by winning games in Season or Exhibition modes.', 'The 2003 edition of the realistic MLB series with updated stats.', 'Experience the thrill of the big leagues in High Heat MLB 2003. Featuring precision batting and deep seasonal play, it’s a must-have for GBA sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-school-musical---livin-the-dream-usir-vg', 'GAMEBOYADVANCE', 'High School Musical - Livin'' the Dream (U)(Sir VG)', '2006', 'Music / Rhythm', 'Artificial Mind & Movement', '1', 'Rhythm', 'Rhythmic platforming and mini-game based adventure inspired by the Disney movie.', 'Complete musical challenges and story missions to live the high school dream.', 'A fun adventure game based on the hit Disney Channel musical movie.', 'Join the East High crew in High School Musical: Livin'' the Dream. Complete puzzles and rhythm games to unlock new content in this vibrant handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hikaru-no-go-jindependent', 'GAMEBOYADVANCE', 'Hikaru no Go (J)(Independent)', '2002', 'Board Game / Strategy', 'Konami', '2', 'Turn-Based', 'Strategic board game simulation based on the traditional game of Go.', 'Master Go tactics to surround territory and defeat your opponents.', 'A tactical Go simulation based on the popular Hikaru no Go anime series.', 'Hikaru no Go for GBA brings the ancient game of Go to life. Learn strategies and climb the ranks in this deep and engaging Japanese board game sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hikaru-no-go-2-jcezar', 'GAMEBOYADVANCE', 'Hikaru no Go 2 (J)(Cezar)', '2003', 'Board Game / Strategy', 'Konami', '2', 'Turn-Based', 'Advanced Go simulation with improved AI and additional story mode elements.', 'Outsmart professional Go players and master complex board strategies.', 'The sequel to the Hikaru no Go simulation with refined gameplay.', 'Hikaru no Go 2 offers an even deeper tactical experience. Challenge the masters of Go and follow the anime storyline in this high-stakes board game sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('himawari-doubutsu-byouin-jcaravan', 'GAMEBOYADVANCE', 'Himawari Doubutsu Byouin (J)(Caravan)', '2003', 'Simulation', 'AlphaDream', '1', 'Life Simulation', 'Medical simulation and pet care mechanics in a veterinary hospital setting.', 'Successfully diagnose and treat various animals to grow your clinic.', 'A charming animal hospital simulation focused on veterinary care.', 'Become a top veterinarian in Himawari Doubutsu Byouin. Diagnose cute pets and use medical tools to heal them in this engaging Japanese simulation game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hime-kishi-monogatari---princess-blue-jchakky', 'GAMEBOYADVANCE', 'Hime Kishi Monogatari - Princess Blue (J)(Chakky)', '2003', 'Role-Playing', 'Game Arts', '1', 'Japanese RPG', 'Tactical turn-based RPG combat mixed with visual novel narrative scenes.', 'Lead your units to victory and protect the kingdom throughout the story.', 'A Japanese strategy RPG featuring a princess-knight protagonist.', 'Hime Kishi Monogatari: Princess Blue combines deep grid-based tactics with royal drama. Command your army and level up your heroes in this classic GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hitsuji-no-kimochi-jindependent', 'GAMEBOYADVANCE', 'Hitsuji no Kimochi (J)(Independent)', '2002', 'Puzzle', 'Success', '1', 'Puzzle', 'Relaxing life simulation and puzzle mechanics with a sheep-herding theme.', 'Manage your flock and complete peaceful tasks in a rural environment.', 'A unique and calming simulation game focused on sheep and nature.', 'Hitsuji no Kimochi offers a tranquil gaming experience. Manage your sheep and enjoy a peaceful pace of life in this unique Japanese GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hobbit-no-bouken-jcaravan', 'GAMEBOYADVANCE', 'Hobbit no Bouken (J)(Caravan)', '2003', 'Action / Adventure', 'Caravan', '1', 'Adventure', 'Action-adventure platformer with puzzle-solving elements in a fantasy world.', 'Journey through Middle-earth to complete the quest and defeat enemies.', 'An adventure game based on the Japanese adaptation of The Hobbit.', 'Explore a fantasy world in Hobbit no Bouken. Solve puzzles and fight mythical creatures in this handheld adventure inspired by classic literature.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-and-pony---lets-ride-2-erising-sun', 'GAMEBOYADVANCE', 'Horse and Pony - Let''s Ride 2 (E)(Rising Sun)', '2005', 'Simulation', 'Tantalus Media', '1', 'Horse Simulation', 'Horse riding and care simulation with equestrian competition mechanics.', 'Train your horse and win various show jumping and racing events.', 'A realistic horse riding simulator with training and grooming features.', 'Let''s Ride 2 puts you in the saddle. Care for your horse and compete in prestigious equestrian events in this detailed GBA simulation game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horse-and-pony---my-stud-farm-erising-sun', 'GAMEBOYADVANCE', 'Horse and Pony - My Stud Farm (E)(Rising Sun)', '2005', 'Simulation', 'Tantalus Media', '1', 'Horse Simulation', 'Management-based simulation focused on running a successful horse farm.', 'Breed, train, and sell horses while managing the farm''s finances.', 'A farm management sim dedicated to the world of horse breeding.', 'My Stud Farm allows you to build your own horse empire. Manage every aspect of your stable to produce champion horses in this deep simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('horsez-uomgba', 'GAMEBOYADVANCE', 'Horsez (U)(OMGba)', '2006', 'Simulation', 'Virtual Toys', '1', 'Horse Simulation', 'Competitive equestrian sports simulation with grooming and riding modes.', 'Reach the top of the horse riding world by winning major competitions.', 'A horse riding adventure focused on professional competition and care.', 'Horsez on GBA offers a complete equestrian experience. Train your horse, manage your stable, and compete for the world championship in this fun sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby---kagami-no-daimeikyuu-jeurasia', 'GAMEBOYADVANCE', 'Hoshi no Kirby - Kagami no Daimeikyuu (J)(Eurasia)', '2004', 'Action / Platformer', 'HAL Laboratory', '1', 'Platformer', 'Non-linear 2D platforming with copy abilities and maze exploration.', 'Find the eight shards of the Dimension Mirror to save Dream Land.', 'An expansive Kirby adventure featuring interconnected worlds and co-op.', 'Kirby & The Amazing Mirror is a Metroidvania-style platformer. Explore a massive world, use iconic copy abilities, and solve puzzles in this GBA masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hoshi-no-kirby---yume-no-izumi-deluxe-jeurasia', 'GAMEBOYADVANCE', 'Hoshi no Kirby - Yume no Izumi Deluxe (J)(Eurasia)', '2002', 'Action / Platformer', 'HAL Laboratory', '1', 'Platformer', 'Classic 2D side-scrolling platformer with power-up progression.', 'Recover the Star Rod from King Dedede to restore dreams to the land.', 'A beautiful GBA remake of the NES classic Kirby''s Adventure.', 'Kirby: Nightmare in Dream Land brings vibrant colors and fluid action to the GBA. Master dozens of abilities in this quintessential Nintendo platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-potato-epatience', 'GAMEBOYADVANCE', 'Hot Potato (E)(Patience)', '2001', 'Party', 'Game Titan', '4', 'Party Game', 'Isometric puzzle-action where you guide a bus through chaotic traffic.', 'Deliver passengers safely while avoiding crashes and obstacles.', 'A quirky and fast-paced puzzle game with a colorful art style.', 'Hot Potato! challenges your reflexes as you navigate a bus through busy streets. Manage your speed and avoid hazards in this unique and addictive puzzler.');
