INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hudson-best-collection-vol-1-jcaravan', 'GAMEBOYADVANCE', 'Hudson Best Collection Vol. 1 (J)(Caravan)', '2003', 'Compilation', 'Hudson Soft', '1', 'Compilation', 'A compilation of 8-bit classics like Bomberman and Star Soldier.', 'Achieve high scores and clear levels in these retro Hudson Soft hits.', 'A collection of the best titles from Hudson Soft''s early library.', 'Hudson Best Collection Vol. 1 is a nostalgic trip. Play pixel-perfect versions of classic arcade and NES games on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hudson-best-collection-vol-4---nazotoki-collection-jsupplex', 'GAMEBOYADVANCE', 'Hudson Best Collection Vol. 4 - Nazotoki Collection (J)(sUppLeX)', '2004', 'Puzzle', 'TOSE', '1', 'Puzzle Collection', 'A collection focused on puzzle-solving and adventure titles from Hudson.', 'Solve complex riddles and navigate through classic adventure stages.', 'A themed collection of Hudson Soft''s best puzzle and mystery games.', 'Hudson Best Collection Vol. 4 brings the "Nazotoki" (riddle) experience to GBA. Challenge your mind with these classic Japanese puzzle gems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hudson-best-collection-vol-5---shooting-collection-jwrg', 'GAMEBOYADVANCE', 'Hudson Best Collection Vol. 5 - Shooting Collection (J)(WRG)', '2004', 'Shooter', 'Hudson Soft', '1', 'Shoot ''em Up', 'A compilation of classic shoot ''em up (SHMUP) games from Hudson Soft.', 'Blast through waves of enemies and survive intense boss battles.', 'A must-have collection for fans of classic arcade shooting games.', 'Hudson Best Collection Vol. 5 features legendary shooters. Experience the fast-paced action of Star Soldier and other 8-bit SHMUP classics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hudson-best-collection-vol-6---bouken-jima-collection-jcaravan', 'GAMEBOYADVANCE', 'Hudson Best Collection Vol. 6 - Bouken Jima Collection (J)(Caravan)', '2004', 'Action / Adventure', 'Hudson Soft', '1', 'Adventure', 'A collection of the iconic Adventure Island platforming series.', 'Help Master Higgins rescue the princess through tropical levels.', 'The complete classic Adventure Island collection for GBA.', 'Hudson Best Collection Vol. 6 brings the tropical platforming of Adventure Island to your pocket. Run, jump, and ride skateboards in this retro bundle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hudson-collection-vol-2---lode-runner-collection-jcaravan', 'GAMEBOYADVANCE', 'Hudson Collection Vol. 2 - Lode Runner Collection (J)(Caravan)', '2004', 'Action / Platformer', 'Hudson Soft', '1', 'Platformer', 'Grid-based puzzle platforming where you dig holes to trap enemies and collect gold.', 'Collect all the gold pieces in each level to reveal the exit ladder and escape.', 'A classic puzzle-platformer collection featuring the legendary Lode Runner series.', 'Hudson Best Collection Vol. 2 brings the complete Lode Runner experience to GBA. Master strategic digging and puzzle-solving across dozens of challenging retro levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hudson-collection-vol-3---action-collection-jcaravan', 'GAMEBOYADVANCE', 'Hudson Collection Vol. 3 - Action Collection (J)(Caravan)', '2004', 'Action', 'Hudson Soft', '1', 'Action Compilation', 'Side-scrolling action and platforming featuring classic Hudson 8-bit characters.', 'Navigate through dangerous levels and defeat bosses to complete the collection.', 'A bundle of Hudson Soft’s most iconic action titles from the Famicom era.', 'Hudson Best Collection Vol. 3 features high-octane 8-bit action. Relive the glory days of Hudson Soft with this perfectly preserved set of classic handheld platformers.');
