INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyokkori-hyotanjima-don-gabacho-daikatsuyaku-no-maki-jrising-sun', 'GAMEBOYADVANCE', 'Hyokkori Hyotanjima Don Gabacho Daikatsuyaku no Maki (J)(Rising Sun)', '2003', 'Action / Adventure', 'Rising Sun', '1', 'Adventure', 'Adventure and puzzle platforming based on the Japanese puppet show.', 'Guide Don Gabacho through various stages to complete his mission.', 'A colorful adventure game based on the classic Japanese TV series.', 'Experience the charm of Hyokkori Hyotanjima on GBA. Join Don Gabacho in a series of fun adventures and puzzles inspired by the beloved Japanese puppet show.');
