INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inukko-club-fukumaru-no-bouken-jpolla', 'GAMEBOYADVANCE', 'Inukko Club Fukumaru no Bouken (J)(Polla)', '2003', 'Action / Adventure', 'Polla', '1', 'Adventure', 'Pet care and adventure simulation featuring adorable dogs and mini-games.', 'Complete quests and care for your canine companions to grow the club.', 'A cute dog-themed simulation game for animal lovers.', 'Inukko Club follows the adventures of Fukumaru. Care for puppies, solve neighborhood mysteries, and enjoy a charming world of dogs on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inuyasha-naraku-no-wana-mayoi-no-mori-no-shoutaijou-jpolla', 'GAMEBOYADVANCE', 'Inuyasha Naraku no Wana Mayoi no Mori no Shoutaijou (J)(Polla)', '2003', 'Action / Role-Playing', 'Dimps', '1', 'Action RPG', 'Tactical RPG with turn-based combat based on the Inuyasha anime series.', 'Follow the map through the forest to uncover Naraku''s traps and defeat him.', 'A strategy-heavy adventure set in the world of Inuyasha and Naraku.', 'Inuyasha: Naraku no Wana is a deep RPG experience. Manage your party, use spiritual attacks, and navigate a dangerous forest to solve the mystery of Naraku.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('invader-evenom', 'GAMEBOYADVANCE', 'Invader (E)(Venom)', '2002', 'Shooter', 'Graphic State', '1', 'Fixed Shooter', 'Vertical scrolling shooter with power-ups and wave-based enemy patterns.', 'Defeat the alien invasion by clearing all sectors and destroying boss ships.', 'A classic arcade-style shoot ''em up with retro space combat.', 'Invader brings old-school arcade shooter vibes to the GBA. Face off against relentless alien swarms and upgrade your ship to save the galaxy from total destruction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iridion-3d-ueurasia', 'GAMEBOYADVANCE', 'Iridion 3D (U)(Eurasia)', '2001', 'Shooter', 'Irem', '1', 'Shoot ''em Up', 'Pseudo-3D rail shooter with high-speed flight mechanics and energy management.', 'Navigate through futuristic landscapes to destroy the Iridion empire.', 'A visually stunning 3D rail shooter with intense space combat.', 'Iridion 3D pushes the GBA hardware with impressive 3D effects. Blast through enemy lines and massive bosses in this high-octane interstellar dogfight.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iridion-ii-eeurasia', 'GAMEBOYADVANCE', 'Iridion II (E)(Eurasia)', '2003', 'Shooter', 'Irem', '1', 'Shoot ''em Up', 'Vertical scrolling shoot ''em up with ship customization and deep scoring.', 'Clear the galaxy of the remaining Iridion forces across multiple planets.', 'The critically acclaimed sequel featuring top-tier 2D SHMUP action.', 'Iridion II is a masterpiece of the genre on GBA. Featuring a fantastic soundtrack and varied ship weapons, it offers some of the best shooting action on the platform.');
