INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('island-xtreme-stunts-uvenom', 'GAMEBOYADVANCE', 'Island Xtreme Stunts (U)(Venom)', '2002', 'Sports / Racing', 'Left Field Productions', '1', 'Extreme Sports', 'Open-world action with vehicle stunts, mini-games, and mission-based tasks.', 'Complete extreme stunts and missions to stop the Brickster''s plans.', 'A LEGO-themed action game focused on extreme sports and vehicles.', 'Island Xtreme Stunts puts you in the role of Pepper Roni. Explore LEGO Island, perform death-defying stunts, and enjoy a variety of high-speed mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('its-mr-pants-urising-sun', 'GAMEBOYADVANCE', 'It''s Mr Pants (U)(Rising Sun)', '2004', 'Puzzle', 'Art Co.', '1', 'Puzzle', 'Quirky puzzle game involving fitting irregular shapes into a grid.', 'Fill the designated area with blocks without overlapping or leaving gaps.', 'A unique and colorful puzzle game developed by Rare for the GBA.', 'It''s Mr. Pants offers a fresh twist on the puzzle genre. Featuring Rare''s signature humor and challenging logic puzzles, it''s a vibrant and addictive brain teaser.');
