INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-pocket-2-jcezar', 'GAMEBOYADVANCE', 'J-League Pocket 2 (J)(Cezar)', '2000', 'Sports', 'Konami', '4', 'Soccer Simulation', 'Refined soccer mechanics with updated rosters and improved AI.', 'Lead your chosen J-League team to victory in the national tournament.', 'The second installment of the portable J-League soccer series.', 'J-League Pocket 2 improves upon the original with better graphics and deeper gameplay. Experience authentic Japanese football action on your Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('j-league-winning-eleven-advance-2002-jeurasia', 'GAMEBOYADVANCE', 'J-League Winning Eleven Advance 2002 (J)(Eurasia)', '2002', 'Sports', 'Konami', '4', 'Soccer Simulation', 'Simulation-based football with realistic physics and official licensing.', 'Master the field and win the J-League season using professional tactics.', 'The GBA version of the famous Winning Eleven (PES) series.', 'J-League Winning Eleven Advance 2002 brings the precision of PES to the GBA. Featuring realistic player movement and deep strategy, it’s a top-tier sports sim.');
