INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-neutron-vs-jimmy-negatron-uvenom', 'GAMEBOYADVANCE', 'Jimmy Neutron vs. Jimmy Negatron (U)(Venom)', '2004', 'Action / Platformer', 'Amaze Entertainment', '1', 'Platformer', 'Multidimensional platformer with character switching and puzzles.', 'Defeat Jimmy''s evil alter-ego, Jimmy Negatron, to save both worlds.', 'An interdimensional adventure featuring Jimmy and his evil twin.', 'Jimmy Neutron vs. Jimmy Negatron features double the trouble! Navigate through alternate dimensions and use gadgets to outsmart the villainous Negatron.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinsei-game-advance-jindependent', 'GAMEBOYADVANCE', 'Jinsei Game Advance (J)(Independent)', '2001', 'Board Game', 'Takara', '4', 'Party Board Game', 'Digital board game simulation with life events and mini-games.', 'Accumulate the most wealth and achieve the best life status by the end.', 'The Japanese version of "The Game of Life" adapted for GBA.', 'Jinsei Game Advance brings the classic board game experience to your handheld. Navigate through life''s milestones, make strategic career choices, and compete for fortune in this engaging Japanese sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jisu-f-zero-weilai-saiche-chigh-road', 'GAMEBOYADVANCE', 'Jisu F-ZERO Weilai Saiche (C)(High-Road)', '2004', 'Racing', 'Nintendo', '2', 'Futuristic Racing', 'High-speed futuristic racing with hover vehicles and energy management.', 'Win the Grand Prix by finishing first on gravity-defying tracks.', 'A fast-paced futuristic racer in the style of the F-Zero series.', 'Experience intense zero-gravity racing in Jisu F-ZERO Weilai Saiche. Master tight corners, manage your boost energy, and outpace rivals in this high-speed sci-fi racing challenge for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jitsutou-pachislo-hisshouhou---juuoh-advance-jindependent', 'GAMEBOYADVANCE', 'Jitsutou Pachislo Hisshouhou - Juuoh Advance (J)(Independent)', '2002', 'Gambling', 'Aruze', '1', 'Pachislot', 'Simulation of a physical Japanese Pachislo slot machine.', 'Hit the jackpot and manage virtual tokens to maximize winnings.', 'A realistic Pachislo simulation featuring the popular Juuoh machine.', 'Jitsutou Pachislo Hisshouhou: Juuoh Advance offers a detailed slot machine experience. Perfect for fans of Japanese gambling sims looking for authentic machine physics and bonus rounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jonny-moseley-mad-trix-umode7', 'GAMEBOYADVANCE', 'Jonny Moseley Mad Trix (U)(Mode7)', '2001', 'Sports / Racing', 'Left Field Productions', '1', 'Extreme Sports', 'Extreme skiing with a focus on aerial tricks and high-speed downhill runs.', 'Perform complex maneuvers to earn high scores and win competitions.', 'An extreme sports game featuring Olympic skier Jonny Moseley.', 'Jonny Moseley Mad Trix delivers arcade-style skiing action. Pull off massive grabs and spins across diverse mountain environments in this fast-paced GBA extreme sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('juka-and-the-monophonic-menace-etrashman', 'GAMEBOYADVANCE', 'Juka and the Monophonic Menace (E)(Trashman)', '2003', 'Action / Platformer', 'Helixe', '1', 'Platformer', 'Isometric action-adventure with alchemy-based puzzle solving.', 'Use sound-based magic and potions to save the land from a mechanical threat.', 'A unique action-adventure game featuring an apprentice alchemist.', 'Juka and the Monophonic Menace blends exploration with clever alchemy mechanics. Collect ingredients, brew potions, and use the power of sound to defeat enemies in this colorful RPG.');
