INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-3---dna-factor-jindependent', 'GAMEBOYADVANCE', 'Jurassic Park 3 - DNA Factor (J)(Independent)', '2001', 'Action / Adventure', 'Griptonite Games', '1', 'Action Adventure', 'Side-scrolling platformer with puzzle-solving and DNA collecting.', 'Collect dinosaur DNA fragments while avoiding prehistoric predators.', 'A 2D platforming adventure set in the Jurassic Park III universe.', 'Jurassic Park III: The DNA Factor combines classic platforming with a unique genetic twist. Navigate dangerous jungles and laboratories to reconstruct dinosaur genomes on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-iii---advanced-action-jeurasia', 'GAMEBOYADVANCE', 'Jurassic Park III - Advanced Action (J)(Eurasia)', '2001', 'Action', 'Konami', '1', 'Action', 'Action-adventure platforming with survival elements and boss fights.', 'Escape Isla Sorna by navigating through dinosaur-infested zones.', 'An intense action game based on the Jurassic Park III movie.', 'Jurassic Park III: Advanced Action puts you in the heart of a dinosaur nightmare. Use your wits and reflexes to survive encounters with Raptors and the Spinosaurus in this handheld thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jurassic-park-iii---dino-attack-elightforce', 'GAMEBOYADVANCE', 'Jurassic Park III - Dino Attack (E)(Lightforce)', '2001', 'Action / Shooter', 'Torus Games', '31-12', 'Arcade Shooter', 'Isometric survival action focusing on stealth and environmental hazards.', 'Reach the extraction point on the island while evading massive dinosaurs.', 'A survival-focused action game set on the dangerous Isla Sorna.', 'In Jurassic Park III: Dino Attack, survival is the only goal. Sneak past hungry predators and solve environmental puzzles to escape the island alive in this tense isometric adventure.');
