INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('justice-league---injustice-for-all-esuxxors', 'GAMEBOYADVANCE', 'Justice League - Injustice for All (E)(Suxxors)', '2002', 'Action / Platformer', 'Snowblind Studios', '1', 'Beat ''em Up', '2D side-scrolling beat ''em up and platformer featuring DC heroes.', 'Stop the Joker and Lex Luthor''s Injustice Gang from taking over.', 'An action game featuring the core members of the Justice League.', 'Justice League: Injustice for All lets you control Superman, Batman, and more. Use unique superhero abilities to fight through iconic DC locations and defeat the world''s greatest villains.');
