INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-koinu-wonderful-jindependent', 'GAMEBOYADVANCE', 'Kawaii Koinu Wonderful (J)(Independent)', '2004', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Pet care simulation focusing on raising and training adorable puppies.', 'Care for your puppy''s needs and win various dog competitions.', 'A charming puppy raising sim for animal lovers on the GBA.', 'Kawaii Koinu Wonderful lets you adopt and raise your dream puppy. From feeding to training, experience the joy of dog ownership in this cute Japanese title.');
