INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kawaii-pet-shop-monogatari-3-jchakky', 'GAMEBOYADVANCE', 'Kawaii Pet Shop Monogatari 3 (J)(Chakky)', '2004', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Shop management simulation with animal care and customer service.', 'Manage a successful pet shop and ensure all animals are healthy.', 'A unique blend of retail management and pet care simulation.', 'Kawaii Pet Shop Monogatari 3 lets you run your own animal business. Source rare pets and satisfy customers in this deep Japanese management sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaze-no-klonoa-2-g2---dream-champ-tournament-jeurasia', 'GAMEBOYADVANCE', 'Kaze no Klonoa 2 G2 - Dream Champ Tournament (J)(Eurasia)', '2002', 'Action / Platformer', 'Namco', '31-12', 'Platformer', '2D puzzle-platforming using unique "grab and throw" mechanics.', 'Win the Dream Champ Tournament by solving complex platform puzzles.', 'A high-quality sequel to the acclaimed Klonoa adventure series.', 'Klonoa 2: Dream Champ Tournament features ingenious puzzle design and fluid 2D action. Help Klonoa navigate tricky levels in this GBA platforming masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keitai-denjuu-telefang-2---power-version-jrapid-fire', 'GAMEBOYADVANCE', 'Keitai Denjuu Telefang 2 - Power Version (J)(Rapid Fire)', '2004', 'Role-Playing', 'Natsume', '1', 'Japanese RPG', 'Monster-battling RPG featuring a phone-based summoning system.', 'Collect "Denjuu" monsters and defeat rivals in turn-based battles.', 'A unique creature-collection RPG with a modern technology twist.', 'Telefang 2: Power Version offers a deep battling experience. Call your monster allies via mobile phone and explore a vast world in this Japanese cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keitai-denjuu-telefang-2---speed-version-jrapid-fire', 'GAMEBOYADVANCE', 'Keitai Denjuu Telefang 2 - Speed Version (J)(Rapid Fire)', '2004', 'Role-Playing', 'Natsume', '1', 'Japanese RPG', 'Monster-battling RPG featuring a phone-based summoning system.', 'Collect "Denjuu" monsters and defeat rivals in turn-based battles.', 'A unique creature-collection RPG with a modern technology twist.', 'Telefang 2: Speed Version provides a different set of monsters and faster gameplay. Build your team and master the turn-based combat system on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kelly-slaters-pro-surfer-umode7', 'GAMEBOYADVANCE', 'Kelly Slater''s Pro Surfer (U)(Mode7)', '2002', 'Sports', 'Treyarch', '1', 'Surfing', 'Realistic surfing simulation with wave physics and trick mechanics.', 'Master the waves and win professional surfing tournaments.', 'An extreme sports game featuring legendary surfer Kelly Slater.', 'Kelly Slater''s Pro Surfer brings authentic wave-riding to the GBA. Perform massive aerials and carves in world-famous locations in this high-energy sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keroro-gunsou-taiketsu!-keroro-cart-de-arimasu!!-jcaravan', 'GAMEBOYADVANCE', 'Keroro Gunsou Taiketsu! Keroro Cart de Arimasu!! (J)(Caravan)', '2004', 'Racing', 'Bandai', '2', 'Arcade Racing', 'Combat kart racing with traps and characters from the Keroro Gunsou anime.', 'Win the planetary races and defeat rival squads in chaotic matches.', 'A fun and wacky kart racer based on the Sgt. Frog anime series.', 'Join Keroro and his platoon in Keroro Cart! Use specialized weapons and character abilities to dominate the track in this colorful GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kessakusen!-ganbare-goemon-1+2-jsupplex', 'GAMEBOYADVANCE', 'Kessakusen! Ganbare Goemon 1+2 (J)(Supplex)', '2005', 'Action / Platformer', 'Now Production', '1', 'Action Compilation', '2D action-platforming featuring iconic Japanese folklore and humor.', 'Complete the classic adventures of Goemon and Ebisumaru.', 'A collection of the first two legendary Ganbare Goemon games.', 'Kessakusen! Ganbare Goemon 1+2 brings 16-bit action to your pocket. Fight through feudal Japan with quirky gadgets and classic platforming gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kid-paddle-eindependent', 'GAMEBOYADVANCE', 'Kid Paddle (E)(Independent)', '2004', 'Action / Platformer', 'Magic Pockets', '1', 'Platformer', 'Action-platformer based on the popular European comic series.', 'Navigate school and fantasy levels while avoiding trouble.', 'A comedic adventure following the life of the gamer Kid Paddle.', 'Kid Paddle for GBA captures the spirit of the comics. Solve puzzles and overcome obstacles in this humor-filled platformer for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kids-cards-utrashman', 'GAMEBOYADVANCE', 'Kid''s Cards (U)(Trashman)', '2001', 'Card Game', 'Majesco', '2', 'Card Game', 'Digital collection of classic card games for younger players.', 'Win various card matches against the computer in games like War.', 'A simple and accessible card game compilation for children.', 'Kid''s Cards offers a variety of easy-to-learn games. Perfect for quick sessions, it features colorful graphics and a kid-friendly interface on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kidou-senshi-gundam-seed-destiny-jcaravan', 'GAMEBOYADVANCE', 'Kidou Senshi Gundam Seed Destiny (J)(Caravan)', '2005', 'Action / Role-Playing', 'Bec', '1', 'Action RPG', '2D fighting game featuring mobile suits from the Gundam Seed series.', 'Defeat rival pilots in high-intensity mecha combat.', 'A fast-paced fighting game based on the Gundam Seed Destiny anime.', 'Pilot your favorite Mobile Suit in Gundam Seed Destiny. Master combos and special moves in this technically impressive GBA fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kikaika-gunta---mech-platoon-jindependent', 'GAMEBOYADVANCE', 'Kikaika Gunta - Mech Platoon (J)(Independent)', '2002', 'Action / Strategy', 'Irem', '31-12', 'Strategy Action', 'Real-time strategy (RTS) with unit building and tactical combat.', 'Manage resources and build a mecha army to defeat the enemy base.', 'A rare and deep real-time strategy game for the GBA.', 'Mech Platoon is one of the few RTS titles on the system. Customise your units and develop complex strategies to conquer the battlefield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiki-kaikai-advance-jeurasia', 'GAMEBOYADVANCE', 'Kiki Kaikai Advance (J)(Eurasia)', '2002', 'Shooter', 'Starfish', '1', 'Shoot ''em Up', 'Top-down shooter with mystical themes and Japanese mythology.', 'Purify spirits and defeat demons using scrolls and projectiles.', 'A classic "cute-''em-up" shooter featuring the shrine maiden Pocky.', 'Kiki Kaikai Advance (Pocky & Rocky) delivers intense shooting action. Battle mythical creatures in this beautifully animated Japanese action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killswitch-erising-sun', 'GAMEBOYADVANCE', 'Kill.Switch (E)(Rising Sun)', '2003', 'Action / Shooter', 'Namco', '1', 'Tactical Shooter', 'Third-person tactical shooter featuring a revolutionary cover system.', 'Use the environment for cover while eliminating enemy forces.', 'A port of the innovative cover-based shooter for the GBA.', 'Kill.Switch brings intense tactical gunplay to a handheld. Master the "blind fire" mechanic and survive high-stakes missions in this action-packed port.');
