INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby---nightmare-in-dreamland-esurplus', 'GAMEBOYADVANCE', 'Kirby - Nightmare in Dreamland (E)(Surplus)', '2002', 'Action / Platformer', 'HAL Laboratory', '1', 'Platformer', 'Side-scrolling platformer with iconic "copy ability" gameplay.', 'Save Dream Land by recovering the Star Rod from King Dedede.', 'A vibrant GBA remake of the classic Kirby''s Adventure.', 'Kirby: Nightmare in Dream Land features beautiful animations and classic fun. Master copy abilities and explore secret areas in this must-play platformer.');
