INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-&-the-amazing-mirror---colored-outlines-usa', 'GAMEBOYADVANCE', 'Kirby & The Amazing Mirror - Colored outlines (USA)', '2004', 'Action / Platformer', 'HAL Laboratory', '4', 'Platformer', 'Non-linear 2D platforming with "copy abilities" and visual character modifications.', 'Explore the Mirror World and defeat Dark Mind with a custom aesthetic.', 'A modified version of Kirby & The Amazing Mirror with colored character outlines.', 'Kirby & The Amazing Mirror - Colored outlines offers a fresh visual twist on the classic Metroidvania-style adventure. Navigate the vast Mirror World with unique character aesthetics while maintaining the original''s deep exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-&-the-amazing-mirror---ex-ability-trio', 'GAMEBOYADVANCE', 'Kirby & The Amazing Mirror - EX Ability Trio', '2004', 'Action / Platformer', 'HAL Laboratory', '3-1', 'Platformer', '2D platforming with a focus on specialized and rare ability combinations.', 'Navigate the interconnected Mirror World using a trio of enhanced abilities.', 'A gameplay-focused modification featuring a specific set of powerful Kirby abilities.', 'Kirby & The Amazing Mirror - EX Ability Trio revamps the combat system. Use specialized power-ups to solve puzzles and defeat bosses in this challenging and strategic fan-made enhancement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-&-the-amazing-mirror---oops!-all-mix!', 'GAMEBOYADVANCE', 'Kirby & The Amazing Mirror - Oops! All Mix!', '2004', 'Action / Platformer', 'HAL Laboratory', '3-1', 'Platformer', 'Randomized 2D platforming where every ability gained is selected via the "Mix" system.', 'Complete the game while adapting to randomized power-ups from every enemy.', 'A chaotic "All Mix" modification that randomizes Kirby''s iconic copy abilities.', 'Kirby & The Amazing Mirror - Oops! All Mix! turns the game into a survival challenge. Adapt your strategy on the fly as your abilities are constantly randomized in this unpredictable GBA hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-&-the-amazing-mirror---shadow-kirby', 'GAMEBOYADVANCE', 'Kirby & The Amazing Mirror - Shadow Kirby', '2004', 'Action / Platformer', 'HAL Laboratory', '4', 'Platformer', '2D platforming action featuring the enigmatic Shadow Kirby as the protagonist.', 'Explore the Mirror World from the perspective of Kirby''s mysterious shadow.', 'A character-swap modification allowing players to control Shadow Kirby.', 'Play as the dark mirror image in Kirby & The Amazing Mirror - Shadow Kirby. Experience the full adventure with unique sprites and a dark aesthetic in this fan-favorite GBA modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-&-the-amazing-mirror-proto', 'GAMEBOYADVANCE', 'Kirby & the Amazing Mirror (Proto)', '2004', 'Action / Platformer', 'HAL Laboratory', '4', 'Platformer', 'Early version of the 2D platformer with unfinished assets and debug features.', 'Test various levels and mechanics of the Mirror World in its early state.', 'A rare prototype build of the acclaimed Kirby & The Amazing Mirror.', 'Kirby & the Amazing Mirror (Proto) offers a fascinating look at game development. Explore early level designs and unused mechanics in this unfinished version of the classic Nintendo handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-and-the-amazing-mirror-erising-sun', 'GAMEBOYADVANCE', 'Kirby And The Amazing Mirror (E)(Rising Sun)', '2004', 'Action / Platformer', 'HAL Laboratory', '4', 'Platformer', 'Interconnected 2D platformer with multi-player support and copy abilities.', 'Reassemble the Dimension Mirror to save the Mirror World and Dream Land.', 'The European release of the non-linear Kirby adventure masterpiece.', 'Kirby & The Amazing Mirror features a massive, open-ended map. Call for help using your cell phone and master various abilities in one of the most ambitious Kirby games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-and-the-amazing-mirror-urising-sun', 'GAMEBOYADVANCE', 'Kirby And The Amazing Mirror (U)(Rising Sun)', '2004', 'Action / Platformer', 'HAL Laboratory', '4', 'Platformer', 'Interconnected 2D platformer with multi-player support and copy abilities.', 'Reassemble the Dimension Mirror to save the Mirror World and Dream Land.', 'The North American release of the non-linear Kirby adventure masterpiece.', 'Kirby & The Amazing Mirror features a massive, open-ended map. Call for help using your cell phone and master various abilities in one of the most ambitious Kirby games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-in-sonic-battle!', 'GAMEBOYADVANCE', 'Kirby in Sonic battle!', '2003', 'Fighting', 'Sonic Team', '2', 'Fighting', 'Fast-paced 2.5D arena fighting using modified Sonic Battle mechanics.', 'Defeat opponents in arena combat using Kirby''s moves in the Sonic universe.', 'A unique crossover modification featuring Kirby in the Sonic Battle engine.', 'Kirby in Sonic Battle! merges two legendary franchises. Use Kirby’s unique fighting style within the high-speed, isometric arena combat engine of Sonic Battle for an explosive GBA experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kirby-red-diamond', 'GAMEBOYADVANCE', 'Kirby Red Diamond', '2002', 'Action / Platformer', 'HAL Laboratory', '1', 'Platformer', 'Traditional 2D platforming with custom levels and increased difficulty.', 'Navigate through new environments to collect the legendary Red Diamonds.', 'A fan-made Kirby adventure with brand new level designs and challenges.', 'Kirby Red Diamond offers a fresh experience for veteran players. Face tougher enemies and navigate complex new platforming stages in this creative and challenging Kirby modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kisekae-angel-jcaravan', 'GAMEBOYADVANCE', 'Kisekae Angel (J)(Caravan)', '2002', 'Simulation', 'Angel', '1', 'Dress-Up Simulation', 'Fashion and lifestyle simulation focused on doll-like character dressing.', 'Create the perfect outfits to win fashion contests and style awards.', 'A cute Japanese fashion simulation game for aspiring stylists.', 'Kisekae Angel lets you express your creativity. Choose from hundreds of clothing items and accessories to style your character in this charming and colorful GBA dress-up game.');
