INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa---empire-of-dreams-erocket', 'GAMEBOYADVANCE', 'Klonoa - Empire of Dreams (E)(Rocket)', '2001', 'Action / Platformer', 'Namco', '1', 'Platformer', '2D puzzle-platforming using the "Wind Bullet" grab and throw mechanic.', 'Travel through the dream empire to stop the King of Despair.', 'A critically acclaimed side-scrolling adventure with deep puzzle mechanics.', 'Klonoa: Empire of Dreams brings vibrant 2D platforming to the GBA. Use enemies as projectiles to solve environmental puzzles and defeat imaginative bosses in this handheld classic.');
