INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa-2---dream-champ-tournament-uvenom', 'GAMEBOYADVANCE', 'Klonoa 2 - Dream Champ Tournament (U)(Venom)', '2005', 'Action / Platformer', 'Namco', '1', 'Platformer', 'Enhanced 2D puzzle-platforming with more complex levels and mechanics.', 'Win the Dream Champ Tournament by outsmarting other dream travelers.', 'The official English release of the second GBA Klonoa adventure.', 'Klonoa 2: Dream Champ Tournament features ingenious level design and smooth animations. Test your brain and reflexes in this definitive puzzle-platformer for the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa-heroes---densetsu-no-star-medal-jeurasia', 'GAMEBOYADVANCE', 'Klonoa Heroes - Densetsu no Star Medal (J)(Eurasia)', '2002', 'Action / Platformer', 'Namco', '1', 'Action Platformer', 'Action RPG with real-time combat and top-down exploration.', 'Level up Klonoa and Guntz to protect the world from dark threats.', 'A unique RPG spin-off of the Klonoa series with deep combat.', 'Klonoa Heroes: Densetsu no Star Medal switches the formula to an action RPG. Explore vast maps, upgrade your gear, and engage in real-time battles in this Japan-exclusive GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koala-brothers-esupplex', 'GAMEBOYADVANCE', 'Koala Brothers (E)(Supplex)', '2004', 'Action / Platformer', 'Magic Pockets', '1', 'Platformer', 'Mini-game collection and adventure based on the children''s TV show.', 'Help the Koala Brothers perform various community tasks and favors.', 'A friendly educational game featuring Frank and Buster.', 'The Koala Brothers on GBA is perfect for younger players. Complete simple puzzles and helpful missions in the Outback in this heartwarming and colorful cartoon adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koinu-to-issho---aijou-monogatari-jtrashman', 'GAMEBOYADVANCE', 'Koinu to Issho - Aijou Monogatari (J)(Trashman)', '2003', 'Simulation', 'MTO', '31-12', 'Pet Simulation', 'Heartwarming pet simulation focusing on raising and training puppies.', 'Nurture your puppy and build a strong emotional bond through care.', 'A touching Japanese puppy raising simulator for animal lovers.', 'Koinu to Issho: Aijou Monogatari allows you to experience the life of a dog owner. Feed, walk, and play with your puppy while witnessing its growth in this detailed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koinu-to-issho-2-jcaravan', 'GAMEBOYADVANCE', 'Koinu to Issho 2 (J)(Caravan)', '2004', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Expanded pet simulation with more puppy breeds and activities.', 'Raise a champion puppy and participate in various neighborhood events.', 'The sequel to the popular Japanese puppy-raising simulation.', 'Koinu to Issho 2 offers more dog breeds and improved interaction. Experience a deeper connection with your virtual pet in this refined GBA sequel for animal fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koinu-chan-no-hajimete-no-osanpo---koino-no-kokoro-ikusei-game-jrising-sun', 'GAMEBOYADVANCE', 'Koinu-Chan no Hajimete no Osanpo - Koino no Kokoro Ikusei Game (J)(Rising Sun)', '2005', 'Simulation', 'MTO', '1', 'Pet Simulation', 'Adventure and care simulation focused on a puppy''s first world exploration.', 'Guide your puppy through its first walks and discover new friends.', 'A gentle adventure game about a young dog learning about the world.', 'Koinu-Chan no Hajimete no Osanpo is a unique "heart-growth" game. Help your puppy overcome fears and learn social skills in this charming Japanese experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-collectors-series---arcade-advanced-jcezar', 'GAMEBOYADVANCE', 'Konami Collector''s Series - Arcade Advanced (J)(Cezar)', '2002', 'Compilation', 'Konami', '1', 'Arcade Compilation', 'Compilation of legendary arcade titles like Frogger and Time Pilot.', 'Achieve high scores and experience pixel-perfect arcade history.', 'A premium collection of Konami’s most famous arcade hits.', 'Konami Collector''s Series: Arcade Advanced brings the arcade home. Enjoy Frogger, Scramble, Gyruss, and more, all optimized for the GBA with modern enhancements.');
