INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-krazy-racers-ecezar', 'GAMEBOYADVANCE', 'Konami Krazy Racers (E)(Cezar)', '2001', 'Racing', 'Konami', '2', 'Arcade Racing', 'Kart racing featuring famous Konami characters and weapon power-ups.', 'Win the Krazy Cup by outracing icons like Goemon and Dracula.', 'A high-quality kart racer often compared to Mario Kart.', 'Konami Krazy Racers is a must-play GBA racer. Choose your favorite Konami legend and speed through imaginative tracks filled with classic franchise references.');
