INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konchu-monster---battle-master-jcaravan', 'GAMEBOYADVANCE', 'Konchu Monster - Battle Master (J)(Caravan)', '2003', 'Role-Playing', 'Caravan', '1', 'Japanese RPG', 'Strategic beetle-fighting and collection RPG.', 'Collect the strongest beetles and win tactical insect battles.', 'A Japanese creature-battling game featuring realistic insects.', 'Konchu Monster: Battle Master lets you experience the world of insect fighting. Collect diverse species and use strategic commands to win the championship in this unique GBA sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konchu-monster---battle-master-stadium-jcaravan', 'GAMEBOYADVANCE', 'Konchu Monster - Battle Master Stadium (J)(Caravan)', '2004', 'Role-Playing', 'Caravan', '31-12', 'Japanese RPG', 'Enhanced beetle-fighting with expanded arenas and tournament modes.', 'Train your insects to dominate the national battle stadium circuit.', 'The competitive sequel to the beetle-battling simulation.', 'Konchu Monster: Battle Master Stadium offers deeper tactical options and more insects to collect. Refine your training methods to become the ultimate insect master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konchu-ouja---mushiking-jcaravan', 'GAMEBOYADVANCE', 'Konchu Ouja - Mushiking (J)(Caravan)', '2003', 'Role-Playing', 'Caravan', '1', 'Japanese RPG', 'Card-based beetle battling simulation based on the arcade sensation.', 'Use rock-paper-scissors tactics to win beetle duels and collect cards.', 'A faithful handheld port of the popular Mushiking arcade game.', 'Konchu Ouja: Mushiking brings the arcade phenomenon to the GBA. Collect powerful beetle cards and master the strategic battle system in this addictive Japanese hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konchuu-no-mori-no-daibouken-jcaravan', 'GAMEBOYADVANCE', 'Konchuu no Mori no Daibouken (J)(Caravan)', '2003', 'Action / Adventure', 'Caravan', '1', 'Adventure', 'Adventure and exploration through a giant world from an insect''s perspective.', 'Survive the dangers of the forest and complete your insect collection.', 'An adventure game set in a vibrant forest full of insects.', 'Konchuu no Mori no Daibouken offers a unique perspective on nature. Explore a massive micro-world, interact with various bugs, and survive the wild as a tiny adventurer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kong---king-of-atlantis-eindependent', 'GAMEBOYADVANCE', 'Kong - King of Atlantis (E)(Independent)', '2005', 'Action / Adventure', '7 Studios', '1', 'Action Adventure', 'Side-scrolling platformer with combat and puzzle-solving elements.', 'Stop the villainous Enno and protect the island of Atlantis.', 'An action-platformer based on the Kong animated movie.', 'Kong: King of Atlantis brings the animated myth to GBA. Navigate treacherous environments, fight ancient guardians, and master Kong''s strength in this cinematic handheld adventure.');
