INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kong---the-animated-series-emenace', 'GAMEBOYADVANCE', 'Kong - The Animated Series (E)(Menace)', '2006', 'Action / Adventure', '7 Studios', '1', 'Action Adventure', '2D side-scrolling action with beat ''em up combat and platforming.', 'Retrieve the primal stones and defeat the evil Ramone De La Porta.', 'An action game based on the Kong: The Animated Series cartoon.', 'Join Kong and his human friends in a race against time. Use brute force and agility to recover mystical stones and defeat global villains in this vibrant GBA action title.');
