INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konjiki-no-gashbell---unare-yuujou-no-zakeru-2-jcaravan', 'GAMEBOYADVANCE', 'Konjiki no Gashbell - Unare Yuujou no Zakeru 2 (J)(Caravan)', '2004', 'Role-Playing', 'Bandai', '1', 'Japanese RPG', '2D arena-based fighting with spell-casting and tag-team mechanics.', 'Defeat rival Mamodo pairs and become the King of the Mamodo world.', 'A fast-paced anime fighting game based on Zatch Bell! (Gashbell).', 'Konjiki no Gashbell 2 offers intense Mamodo battles. Unleash powerful spells like Zakeru and build strong bonds with your partner to dominate the combat arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konjiki-no-gashbell-jeurasia', 'GAMEBOYADVANCE', 'Konjiki no Gashbell (J)(Eurasia)', '2003', 'Role-Playing', 'Bandai', '31-12', 'Japanese RPG', '2D arena-based fighting with spell-casting and tag-team mechanics.', 'Defeat rival Mamodo pairs and become the King of the Mamodo world.', 'A fast-paced anime fighting game based on Zatch Bell! (Gashbell).', 'Konjiki no Gashbell 2 offers intense Mamodo battles. Unleash powerful spells like Zakeru and build strong bonds with your partner to dominate the combat arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konjiki-no-gashbell!!-makai-no-bookmark-jcaravan', 'GAMEBOYADVANCE', 'Konjiki no Gashbell!! Makai no Bookmark (J)(Caravan)', '2004', 'Role-Playing', 'Bandai', '1', 'Japanese RPG', 'Strategy RPG with turn-based combat and exploration elements.', 'Find the mysterious bookmarks and defeat the dark forces of the Mamodo world.', 'An RPG adventure set in the popular Zatch Bell! universe.', 'Explore the world of Zatch Bell in Makai no Bookmark. Assemble your team of Mamodo, strategically manage your spells, and uncover a brand new story on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konjiki-no-gashbell!!-the-card-battle-for-gba-jsupplex', 'GAMEBOYADVANCE', 'Konjiki no Gashbell!! The Card Battle for GBA (J)(Supplex)', '2004', 'Card Game', 'Bandai', '1-1', 'Card Battle', 'Card-based strategy game with deck building and tactical duels.', 'Use your spell cards and Mamodo units to defeat opponents in battle.', 'A faithful adaptation of the Zatch Bell! trading card game.', 'Master the rules of the Mamodo card game in this strategic GBA title. Build a custom deck, manage your heart power, and outsmart rivals with iconic anime spells.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konjiki-no-gashbell!!-yuujou-no-dengeki-dream-tag-tournament-jwrg', 'GAMEBOYADVANCE', 'Konjiki no Gashbell!! Yuujou no Dengeki Dream Tag Tournament (J)(WRG)', '2004', 'Fighting', 'Bandai', '2', 'Arena Fighting', 'Tag-team arena fighting with specialized partner combos and specials.', 'Win the ultimate Mamodo tournament by mastering dual-character tactics.', 'A competitive anime fighter focused on dream team combinations.', 'Dream Tag Tournament takes Gashbell battles to the next level. Choose your favorite duo and perform devastating tag-team attacks in this high-energy GBA fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koopa-troopa-smk', 'GAMEBOYADVANCE', 'Koopa Troopa (SMK)', '1990', 'Action / Platformer', 'Nintendo', '1', 'Platformer', 'Mode-7 style kart racing featuring the iconic Koopa Troopa character.', 'Win the mushroom cup by drifting and using classic power-ups.', 'A character-focused kart racer based on the Super Mario Kart engine.', 'Speed through the tracks as Koopa Troopa! Master the power-sliding mechanics and use shells to take out your rivals in this classic 16-bit style racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kootetsu-teikoku-from-hot-b-jeurasia', 'GAMEBOYADVANCE', 'Kootetsu Teikoku from Hot-B (J)(Eurasia)', '2004', 'Action / Strategy', 'Hot-B', '1', 'Strategy Action', 'Side-scrolling shoot ''em up with steampunk aesthetics and ship upgrades.', 'Defeat the high-tech empire using your customizable flying machines.', 'A visually striking steampunk SHMUP also known as Steel Empire.', 'Steel Empire brings epic aerial combat to GBA. Maneuver through industrial landscapes and destroy massive bosses in this acclaimed retro shooter port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koro-koro-puzzle-happy-panechu!-jnobody', 'GAMEBOYADVANCE', 'Koro Koro Puzzle Happy Panechu! (J)(Nobody)', '2002', 'Puzzle', 'Jupiter', '1', 'Puzzle', 'Tile-matching puzzle game with a unique tilt-mechanic for clearing blocks.', 'Connect and clear "Panechu" creatures using color-matching and movement.', 'A quirky and innovative Japanese puzzle game with a motion-style feel.', 'Happy Panechu! is a colorful and addictive brain teaser. Use the game''s unique movement physics to clear the screen and achieve high scores in this GBA puzzle gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korokke-great-toki-no-boukensha-jcaravan', 'GAMEBOYADVANCE', 'Korokke Great Toki no Boukensha (J)(Caravan)', '2004', 'Action / Role-Playing', 'Caravan', '1', 'Action RPG', 'Action RPG with real-time combat and a focus on "Bunker" collecting.', 'Embark on a journey to find the legendary Great Bunker and save the world.', 'An adventure RPG based on the popular Croket! manga and anime.', 'Join Korokke on a grand adventure! Fight enemies in real-time, level up your skills, and explore a vibrant world in this action-packed Japanese GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korokke-yume-no-bunker-survival-jpatience', 'GAMEBOYADVANCE', 'Korokke Yume no Bunker Survival (J)(Patience)', '2005', 'Action / Role-Playing', 'Caravan', '1', 'Action RPG', 'Strategic battle game with collection and character-building elements.', 'Compete in the Bunker survival tournament to become the top hunter.', 'A survival-style tactical game based on the Croket! series.', 'Navigate the challenges of the Bunker Survival world. Build your character''s stats and outplay rivals in this unique blend of strategy and anime action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kotoba-no-puzzle-mojipittan-advance-jsuxxors', 'GAMEBOYADVANCE', 'Kotoba no Puzzle Mojipittan Advance (J)(Suxxors)', '2004', 'Puzzle', 'Namco', '1', 'Word Puzzle', 'Japanese word-based puzzle game focusing on building vocabulary.', 'Create as many Japanese words as possible on the grid to score points.', 'A handheld version of the popular Namco word-puzzle series.', 'Mojipittan Advance challenges your brain and vocabulary. Place hiragana tiles strategically to form chains of words in this highly addictive and charming puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kunio-kun-nekketsu-collection-1-jwrg', 'GAMEBOYADVANCE', 'Kunio kun Nekketsu Collection 1 (J)(WRG)', '2003', 'Action / Platformer', 'Technos Japan', '2', 'Action Compilation', 'Compilation of classic 8-bit beat ''em up and sports titles.', 'Defeat rival gangs and win sports tournaments as Kunio and Riki.', 'A retro collection of the famous Nekketsu / River City Ransom games.', 'Relive the glory of the 8-bit era with Kunio-kun Collection 1. Fight through the streets or compete in dodgeball in these perfectly preserved retro classics.');
