INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuniokun-nekketsu-collection-3-jcaravan', 'GAMEBOYADVANCE', 'Kuniokun Nekketsu Collection 3 (J)(Caravan)', '2005', 'Action / Platformer', 'Technos Japan', '2', 'Action Compilation', 'Compilation of classic 8-bit beat ''em up and sports titles.', 'Defeat rival gangs and win sports tournaments as Kunio and Riki.', 'A retro collection of the famous Nekketsu / River City Ransom games.', 'Relive the glory of the 8-bit era with Kunio-kun Collection 1. Fight through the streets or compete in dodgeball in these perfectly preserved retro classics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurohige-no-golf-shiyouyo-jzbb', 'GAMEBOYADVANCE', 'Kurohige no Golf Shiyouyo (J)(ZBB)', '2003', 'Sports', 'Konami', '1', 'Golf Simulation', 'Arcade-style golf simulation with a focus on accessible controls.', 'Win tournaments and unlock new characters on the golf course.', 'A lighthearted golf game featuring the Kurohige (Pop-up Pirate) brand.', 'Hit the green with Kurohige no Golf! Experience fun and accessible golfing mechanics with a cast of colorful characters in this casual sports title for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurohige-no-kurutto-jintori-jindependent', 'GAMEBOYADVANCE', 'Kurohige no Kurutto Jintori (J)(Independent)', '2003', 'Party', 'Game Freak', '4', 'Party Game', 'Grid-based board game focused on capturing territory and trapping rivals.', 'Capture more squares than your opponent to win the match.', 'A tactical territory-capture game featuring the Kurohige pirate.', 'Plan your moves carefully in this unique board game. Trap your opponents and expand your territory to claim victory in this strategy-heavy Japanese GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuru-kuru-kururin-emode7', 'GAMEBOYADVANCE', 'Kuru Kuru Kururin (E)(Mode7)', '2001', 'Puzzle', 'Eighting', '1', 'Precision Puzzle', 'Rotating action-puzzle game where you guide a spinning stick through mazes.', 'Navigate through tight corridors without touching the walls to reach the goal.', 'A unique and highly challenging puzzle-action game from Nintendo.', 'Kuru Kuru Kururin is a test of precision and nerves. Maneuver your spinning ship through increasingly complex obstacles in this creative and colorful GBA classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuru-kuru-kururin-jeurasia', 'GAMEBOYADVANCE', 'Kuru Kuru Kururin (J)(Eurasia)', '2001', 'Puzzle', 'Eighting', '1', 'Precision Puzzle', 'Rotating action-puzzle game where you guide a spinning stick through mazes.', 'Navigate through tight corridors without touching the walls to reach the goal.', 'A unique and highly challenging puzzle-action game from Nintendo.', 'Kuru Kuru Kururin is a test of precision and nerves. Maneuver your spinning ship through increasingly complex obstacles in this creative and colorful GBA classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kururin-paradise-jgbatemp', 'GAMEBOYADVANCE', 'Kururin Paradise (J)(GBATemp)', '2002', 'Puzzle', 'Eighting', '1', 'Precision Puzzle', 'Enhanced rotating puzzle-action with more levels and mini-games.', 'Save the Kururin family by mastering even more complex spinning mazes.', 'The Japan-exclusive sequel to the hit puzzle-action game.', 'Kururin Paradise takes the spinning mechanics to the extreme. Enjoy new power-ups, fun mini-games, and a vibrant world in this superior puzzle sequel for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kururin-paradise-japan-t-en-by-dimedime-v10', 'GAMEBOYADVANCE', 'Kururin Paradise (Japan) [T-En by Dimedime v1.0]', '2002', 'Puzzle', 'Eighting', '1', 'Precision Puzzle', 'Enhanced rotating puzzle-action with more levels and mini-games.', 'Save the Kururin family by mastering even more complex spinning mazes.', 'The Japan-exclusive sequel to the hit puzzle-action game.', 'Kururin Paradise takes the spinning mechanics to the extreme. Enjoy new power-ups, fun mini-games, and a vibrant world in this superior puzzle sequel for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('la-famille-de-la-jungle---a-la-poursuite-de-darwin-fpatience', 'GAMEBOYADVANCE', 'La Famille De La Jungle - A La Poursuite De Darwin (F)(Patience)', '2006', 'Action / Adventure', 'MTO', '1', 'Adventure', 'Side-scrolling adventure with puzzle-solving and character exploration.', 'Help Eliza and the Wild Thornberrys rescue Darwin from his captors.', 'An adventure game based on the Nickelodeon animated series.', 'Explore the African savanna and beyond in this Wild Thornberrys adventure. Use Eliza’s animal-speaking skills to solve puzzles and bring Darwin home safely.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('la-famille-delajungle---le-film-feternity', 'GAMEBOYADVANCE', 'La famille Delajungle - Le Film (F)(Eternity)', '2006', 'Action / Adventure', 'MTO', '1', 'Adventure', 'Mini-game based adventure featuring the plot of the animated film.', 'Complete various wildlife challenges to follow the movie''s storyline.', 'A movie-tie-in game featuring the Wild Thornberrys family.', 'Relive the excitement of the big screen on your GBA. Engage in diverse missions and interact with exotic wildlife in this faithful adaptation of the Thornberrys'' movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('la-gang-del-bosco-iindependent', 'GAMEBOYADVANCE', 'La Gang del Bosco (I)(Independent)', '2005', 'Action / Adventure', 'MTO', '1', 'Adventure', 'Isometric stealth and action-adventure featuring forest animals.', 'Forage for food and complete tasks while avoiding human detection.', 'An action game based on the DreamWorks film Over the Hedge.', 'Join RJ and Verne in a quest for snacks! Navigate through backyard obstacles, use stealth to avoid the Exterminator, and help the gang survive the hedge in this fun GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lady-sia-emode7', 'GAMEBOYADVANCE', 'Lady Sia (E)(Mode7)', '2001', 'Action / Platformer', 'R.A.M. Software', '1', 'Platformer', '2D side-scrolling action platformer with sword combat and magic.', 'Defeat the Beast Legion and reclaim your kingdom as Princess Sia.', 'A cult classic 2D action game with high-quality hand-drawn graphics.', 'Lady Sia is a hidden gem of the GBA era. Master the art of the sword and elemental magic in this beautifully animated and challenging fantasy platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lady-sia-umugs', 'GAMEBOYADVANCE', 'Lady Sia (U)(MUGS)', '2001', 'Action / Platformer', 'R.A.M. Software', '1', 'Platformer', '2D side-scrolling action platformer with sword combat and magic.', 'Defeat the Beast Legion and reclaim your kingdom as Princess Sia.', 'A cult classic 2D action game with high-quality hand-drawn graphics.', 'Lady Sia is a hidden gem of the GBA era. Master the art of the sword and elemental magic in this beautifully animated and challenging fantasy platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('land-before-time---into-the-mysterious-land-erising-sun', 'GAMEBOYADVANCE', 'Land Before Time - Into the Mysterious Land (E)(Rising Sun)', '2002', 'Action / Adventure', 'KnowWonder', '1', 'Adventure', '2D side-scrolling platformer with character-switching mechanics.', 'Guide Littlefoot and his friends to find the Mysterious Land and reunite with their families.', 'A prehistoric adventure based on the classic animated film series.', 'Join Littlefoot and his dinosaur friends in Land Before Time: Into the Mysterious Land. Navigate lush environments, solve puzzles, and avoid predators in this family-friendly GBA platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lara-croft---tomb-raider-legend-erising-sun', 'GAMEBOYADVANCE', 'Lara Croft - Tomb Raider Legend (E)(Rising Sun)', '2006', 'Action / Adventure', 'Griptonite Games', '1', 'Action Adventure', 'Isometric action-adventure focusing on platforming, puzzles, and combat.', 'Recover the pieces of Excalibur while uncovering Lara''s mother''s past.', 'A handheld adaptation of the hit Tomb Raider reboot for GBA.', 'Experience Lara Croft''s global adventure in Tomb Raider Legend. Master acrobatics, explore ancient ruins, and solve environmental puzzles in this technically impressive isometric action title.');
