INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lara-croft-tomb-raider---the-prophecy-emode7', 'GAMEBOYADVANCE', 'Lara Croft Tomb Raider - The Prophecy (E)(Mode7)', '2002', 'Action / Adventure', 'Core Design', '1', 'Action Adventure', 'Top-down action-adventure with dual-pistol combat and puzzle-solving.', 'Prevent a dark prophecy from coming true by exploring ancient sites.', 'An original GBA Tomb Raider adventure with a top-down perspective.', 'Lara Croft Tomb Raider: The Prophecy offers unique top-down exploration. Fight supernatural foes and collect mystical artifacts as you travel through snowy mountains and deep tombs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lara-croft-tomb-raider---the-prophecy-jmugs', 'GAMEBOYADVANCE', 'Lara Croft Tomb Raider - The Prophecy (J)(Mugs)', '2002', 'Action / Adventure', 'Core Design', '1', 'Action Adventure', 'Top-down action-adventure with dual-pistol combat and puzzle-solving.', 'Prevent a dark prophecy from coming true by exploring ancient sites.', 'An original GBA Tomb Raider adventure with a top-down perspective.', 'Lara Croft Tomb Raider: The Prophecy offers unique top-down exploration. Fight supernatural foes and collect mystical artifacts as you travel through snowy mountains and deep tombs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lea---passion-veterinaire-fsupplex', 'GAMEBOYADVANCE', 'Lea - Passion Veterinaire (F)(sUppLeX)', '2004', 'Simulation', 'Tate Interactive', '1', 'Veterinary Simulation', 'Veterinary simulation with medical diagnosis and animal care mini-games.', 'Treat sick animals and successfully run your own veterinary clinic.', 'A charming animal care simulator part of the "Lea''s Passion" series.', 'Become a professional vet in Lea - Passion Veterinaire. Care for various animals, diagnose their illnesses, and learn about the world of veterinary medicine in this detailed GBA sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-dynamic---goushouden-jrising-sun', 'GAMEBOYADVANCE', 'Legend of Dynamic - Goushouden (J)(Rising Sun)', '2004', 'Fighting', 'Banpresto', '2', 'Fighting', 'Strategic RPG with turn-based combat featuring Go Nagai characters.', 'Defeat powerful enemies using a team of legendary anime heroes.', 'A crossover tactical RPG featuring famous characters like Mazinger Z.', 'Legend of Dynamic: Goushouden brings Go Nagai’s iconic creations together. Command powerful units in strategic turn-based battles and experience a unique crossover story on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legends-of-wrestling-2-uvenom', 'GAMEBOYADVANCE', 'Legends of Wrestling 2 (U)(Venom)', '2002', 'Fighting', 'Acclaim', '4', 'Wrestling', 'Arcade-style professional wrestling with a roster of legendary icons.', 'Win championships and dominate the ring in various match types.', 'A wrestling game featuring legends like Hulk Hogan and Andre the Giant.', 'Legends of Wrestling 2 brings old-school mayhem to the GBA. Choose from a massive roster of icons and execute signature moves to pin your opponents in the squared circle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legendz---buhwarhaneun-siryeonyi-seom-kac8', 'GAMEBOYADVANCE', 'Legendz - Buhwarhaneun Siryeonyi Seom (K)(AC8)', '2004', 'Role-Playing', 'Bandai', '1', 'Japanese RPG', 'Creature-collecting RPG with turn-based battles and exploration.', 'Collect and train Legendz monsters to become the ultimate champion.', 'A monster-battling adventure based on the Legendz franchise.', 'Legendz: Buhwarhaneun Siryeonyi Seom features deep creature customization. Explore a vibrant world, train your monsters, and master the turn-based combat system in this Korean-exclusive title.');
