INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legions---yomigaeru-shiren-no-shima-jhyperion', 'GAMEBOYADVANCE', 'Legions - Yomigaeru Shiren no Shima (J)(Hyperion)', '2002', 'Action / Adventure', 'Koei', '1', 'Adventure', 'Strategy-focused island exploration and creature collection.', 'Survive the trials of the island and uncover the secrets of the Legions.', 'A tactical adventure game featuring monster recruitment and growth.', 'Legions: Yomigaeru Shiren no Shima combines strategy with exploration. Build a powerful team of creatures and navigate a dangerous island to uncover ancient mysteries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-2-in-1---bionicle-and-knights-kingdom-esupplex', 'GAMEBOYADVANCE', 'Lego 2 in 1 - Bionicle and Knights Kingdom (E)(Supplex)', '2004', 'Action / Adventure', 'Climax Group', '1', 'Action Adventure', 'A double-pack compilation featuring two complete LEGO action titles.', 'Complete the elemental quests in Bionicle and save the kingdom in Knights Kingdom.', 'Two LEGO GBA classics in one cartridge for double the adventure.', 'LEGO 2 in 1 offers massive value. Battle as elemental Toa in Bionicle and embark on heroic quests in Knights Kingdom, all within this comprehensive handheld package.');
