INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-racers-2-eindependent', 'GAMEBOYADVANCE', 'Lego Racers 2 (E)(Independent)', '2005', 'Racing', 'Tantalus Media', '4', 'Arcade Racing', '3D-style kart racing with vehicle customization and power-ups.', 'Win the galactic racing tournament and build the ultimate racer.', 'A high-speed sequel to the popular LEGO Racers series.', 'LEGO Racers 2 offers open-world racing hubs and customizable cars. Explore different LEGO themes and win races to collect golden bricks on your GBA.');
