INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-jcaravan', 'GAMEBOYADVANCE', 'Lego Star Wars (J)(Caravan)', '2005', 'Action / Role-Playing', 'Amaze Entertainment', '1', 'Action RPG', 'Isometric action-adventure following the Star Wars prequel trilogy.', 'Battle as Jedi and Clone Troopers to complete movie-based missions.', 'A charming brick-based retelling of the Star Wars prequel films.', 'LEGO Star Wars brings the galaxy far, far away to GBA. Use Force powers and lightsabers to fight through iconic scenes from the first three episodes.');
