INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-star-wars-ii---the-original-trilogy-erising-sun', 'GAMEBOYADVANCE', 'LEGO Star Wars II - The Original Trilogy (E)(Rising Sun)', '2006', 'Action / Adventure', 'Amaze Entertainment', '1', 'Action Adventure', 'Isometric action-adventure following the Star Wars original trilogy.', 'Play as Luke, Leia, and Han to defeat the Empire and Darth Vader.', 'The brick-based sequel focusing on Episodes IV, V, and VI.', 'LEGO Star Wars II: The Original Trilogy offers classic space-opera action. Switch between iconic characters and use the Force to solve puzzles in this GBA sequel.');